"""Create a protected local Firely snapshot and patch the existing reviewer portal.
No AWS API calls. Existing containers and databases are retained.
Run with the project's document-tools-venv Python from the Mac.
"""
import hashlib
import json
import shutil
import socket
import ssl
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path
from urllib.error import HTTPError
from urllib.request import Request, urlopen

ROOT = Path.home() / 'firely-learning'
CONTAINER = 'firely-learning-local-secure'
APPOINTMENT = 'siu-appointment-17d6d563-4f77-5aac-b49b-2367195f7423'
RESOURCE_PATHS = [
    'Patient/demo-patient-002', 'Observation/demo-glucose-002',
    'Observation/lab-760b9ffe-19ca-5dbb-b2ef-8bb12d2cf2d4',
    'Appointment/' + APPOINTMENT,
]

class SetupError(Exception):
    pass

def command(args):
    try:
        result = subprocess.run(args, capture_output=True, text=True, timeout=75)
    except (OSError, subprocess.TimeoutExpired):
        raise SetupError('Local command unavailable or timed out; no raw configuration was printed.') from None
    if result.returncode:
        raise SetupError('Local command failed: ' + ' '.join(args[:2]) + '. Stop here and share this message.')
    return result.stdout

def inspect(name):
    return json.loads(command(['docker', 'inspect', name]))[0]

def endpoint(url, ca=None):
    context = ssl.create_default_context(cafile=str(ca)) if ca else None
    try:
        with urlopen(Request(url, headers={'Accept':'application/fhir+json'}), context=context, timeout=4) as response:
            return response.status, response.read(8 * 1024 * 1024)
    except HTTPError as error:
        return error.code, b''

def wait_for(url, expected, ca=None):
    for attempt in range(45):
        try:
            status, body = endpoint(url, ca)
            if status == expected:
                return body
        except (OSError, ValueError):
            pass
        if attempt in (0, 10, 20, 30, 40):
            print('Waiting for local service:', url.split('/')[2], flush=True)
        time.sleep(2)
    raise SetupError('Local service did not pass its check: ' + url.split('/')[2])

def container_args(source, data, license_path):
    env = dict(value.split('=',1) for value in source['Config'].get('Env',[]))
    smart = {k:v for k,v in env.items() if k.startswith('VONK_SmartAuthorizationOptions__')}
    for key in ('Enabled','EnforceAccessPolicies'):
        if smart.get('VONK_SmartAuthorizationOptions__'+key,'').lower() != 'true':
            raise SetupError('Existing SMART authorization is not enabled and enforced; nothing was changed.')
    for key in ('Authority','Audience','Protected__InstanceLevelInteractions',
                'Protected__TypeLevelInteractions','Protected__WholeSystemInteractions'):
        if not smart.get('VONK_SmartAuthorizationOptions__'+key):
            raise SetupError('Existing SMART authorization setting missing: '+key)
    args=['docker','create','--name',CONTAINER,'--label','firely.learning.mode=local-secure-copy',
          '-p','127.0.0.1:8081:4080','-v',str(data)+':/app/data',
          '-v',str(license_path)+':/app/firelyserver-license.json:ro']
    network=source.get('HostConfig',{}).get('NetworkMode','bridge')
    if network not in ('bridge','default',''):
        if network == 'host' or network.startswith('container:'):
            raise SetupError('Unexpected network mode; local setup stopped.')
        args += ['--network',network]
    for host in source.get('HostConfig',{}).get('ExtraHosts') or []:
        args += ['--add-host',host]
    settings={**smart,'VONK_Repository':'SQLite','VONK_Administration__Repository':'SQLite',
              'VONK_SQLiteDbOptions__ConnectionString':'Data Source=./data/vonkdata.db;Cache=Shared',
              'VONK_Administration__SQLiteDbOptions__ConnectionString':'Data Source=./data/vonkadmin.db;Cache=Shared'}
    for key,value in settings.items():
        args += ['-e',key+'='+value]
    args.append(source['Image'])  # Exact installed image ID, including provider trust.
    return args

def validate_files():
    for name, expected in ORIGINALS.items():
        path=ROOT/name
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=expected:
            raise SetupError('Source changed or missing: '+name+'. Stop and share this message before editing.')
    for name in ('worklist/viewer_server.py','worklist/data/worklist.sqlite',
                 'firelyserver-license.json','auth/certs/local-rootCA.crt',
                 'auth/certs/localhost.pem','auth/certs/localhost-key.pem'):
        if not (ROOT/name).is_file():
            raise SetupError('Required local file missing: '+name)
    if (ROOT/'worklist/spec/v2/local-integration.json').exists():
        raise SetupError('A local integration is already configured. Do not rerun setup; use its saved startup instructions.')
    for port in (8081,8082):
        with socket.socket() as sock:
            try:
                sock.bind(('127.0.0.1',port))
            except OSError:
                raise SetupError('Port '+str(port)+' is in use. Close the old viewer/service, then rerun.')

def main():
    validate_files()
    original=inspect('firely-learning')
    secured=inspect('firely-learning-aws')
    if original['State']['Status']!='running':
        raise SetupError('Start the original local Firely first: docker start firely-learning')
    if secured['State']['Status']=='running':
        raise SetupError('The AWS-backed container is running; stop it before using local port 8081.')
    # All prerequisite checks happen before touching any service or project file.
    mounts={m['Destination']:Path(m['Source']) for m in original['Mounts']}
    if mounts.get('/app/data') != ROOT/'data':
        raise SetupError('Original data mount differs from the inspected project; nothing was changed.')
    destination=ROOT/'local-secure-data'
    if destination.exists():
        raise SetupError('local-secure-data already exists; stop here to preserve it.')
    names=command(['docker','ps','-a','--format','{{.Names}}']).splitlines()
    if CONTAINER in names:
        raise SetupError('The local secure container already exists; stop here instead of replacing it.')
    args=container_args(secured,destination,ROOT/'firelyserver-license.json')
    baseline={}
    for path in RESOURCE_PATHS:
        status,raw=endpoint('http://localhost:8080/'+path)
        if status!=200:
            raise SetupError('Original local resource could not be read: '+path)
        resource=json.loads(raw)
        if resource.get('resourceType')+'/'+resource.get('id','')!=path:
            raise SetupError('Original local resource identity mismatch: '+path)
        baseline[path]=resource
    checkpoint=ROOT/'checkpoints'/('local-portal-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
    checkpoint.mkdir(parents=True)
    for name in PATCHES:
        source=ROOT/name
        if source.exists():
            backup=checkpoint/name
            backup.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(source,backup)
    (checkpoint/'source-resources.json').write_text(json.dumps(baseline,indent=2)+'\n')
    created=False
    changed=[]
    print('Checkpoint:',checkpoint,flush=True)
    try:
        # Stop briefly so the SQLite copy includes one quiet filesystem state.
        command(['docker','stop','firely-learning'])
        try:
            shutil.copytree(ROOT/'data',destination)
        finally:
            command(['docker','start','firely-learning'])
        print('PASS: original local Firely restarted; its data was copied.',flush=True)
        command(args)
        created=True
        command(['docker','start','firely-learning-mailpit','firely-learning-auth',CONTAINER])
        ca=ROOT/'auth/certs/local-rootCA.crt'
        discovery=json.loads(wait_for('https://localhost:5001/.well-known/openid-configuration',200,ca))
        if discovery.get('issuer')!='https://localhost:5001':
            raise SetupError('Authentication issuer did not match; portal changes were not installed.')
        print('PASS: authentication provider is reachable with trusted TLS.',flush=True)
        wait_for('http://localhost:8081/$readiness',200)
        for path in RESOURCE_PATHS:
            status,_=endpoint('http://localhost:8081/'+path)
            if status!=401:
                raise SetupError('Anonymous FHIR read was not rejected with HTTP 401; secure local container stopped.')
        print('PASS: all four FHIR resources reject anonymous reads (HTTP 401).',flush=True)
        for name,text in PATCHES.items():
            target=ROOT/name
            target.parent.mkdir(parents=True,exist_ok=True)
            target.write_text(text)
            changed.append(name)
        # Exact snapshot is retained for the real authenticated read-back check.
        mode=ROOT/'worklist/spec/v2/local-integration.json'
        config=json.loads(mode.read_text())
        config['checkpoint']=str(checkpoint)
        mode.write_text(json.dumps(config,indent=2)+'\n')
        instructions={
            'checkpoint':str(checkpoint),'container':CONTAINER,'patched_files':changed,
            'new_files':[name for name in PATCHES if not (checkpoint/name).exists()],
            'source_resources':str(checkpoint/'source-resources.json'),
        }
        (checkpoint/'setup.json').write_text(json.dumps(instructions,indent=2)+'\n')
        print('PASS: new appointment assigned; original patient reference aliases supported.',flush=True)
        print('PASS: portal patches installed; worklist database was not modified.',flush=True)
        print('SETUP COMPLETE. Authenticated clinical read-back still requires your normal login.',flush=True)
        print('Next command:\n'+str(ROOT/'document-tools-venv/bin/python')+' '+str(ROOT/'worklist/authenticated_viewer_server.py'))
    except Exception:
        for name in changed:
            backup=checkpoint/name
            target=ROOT/name
            if backup.exists(): shutil.copy2(backup,target)
            else: target.unlink(missing_ok=True)
        if created:
            try: command(['docker','stop',CONTAINER])
            except SetupError: pass
        print('STOP: portal file changes rolled back. Original data and AWS container retained.',flush=True)
        print('Retained checkpoint:',checkpoint,flush=True)
        raise

